art_schema.content:
Table projects {
  id text [pk]
  name text [not null]
}

Table work_items {
  id text [pk]
  project_id text [ref: > projects.id]
  title text [not null]
  state text
  source text
}

Table github_issues {
  id text [pk]
  work_item_id text [ref: > work_items.id]
  repo text [not null]
  number int [not null]
}

